{"task_id": "T43", "code": "def solve(coins, amount):
    # Edge cases
    if amount == 0:
        return 0
    # Filter out non-positive coins (zero or negative) as they don't help
    coins = sorted({c for c in coins if c > 0})
    if not coins:
        return -1
    # Quick answer if coin 1 is present
    if 1 in coins:
        return amount
    # If smallest coin greater than amount, impossible
    if coins[0] > amount:
        return -1
    # Compute gcd of coins; if amount not divisible, impossible
    from math import gcd
    g = coins[0]
    for c in coins[1:]:
        g = gcd(g, c)
    if amount % g != 0:
