import heapq

def solve(n, edges):
    indeg = [0]*n
    adj = [[] for _ in range(n)]
    for a,b in edges:
        adj[a].append(b)
        indeg[b]+=1
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order=[]
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in sorted(adj[u]):
            indeg[v]-=1
            if indeg[v]==0:
                heapq.heappush(heap, v)
    if len(order)!=n:
        return []
    return order

